// action.rue by yakuhito
// Inner puzzle for a singleton that has a state and may run any of n actions
// Each action will receive the current state + an ephemeral state and return new values
// One or more actions may be run per spend

// An action's solution will always be: (c (c Ephemeral_State Current_State) solution)
//    (where capital first letters are used to denote Truths)
// It returns three values: ((new_ephemeral_state . new_state) . new_conditions)
//    state is passed from one action to the next and the latest value is saved between spends
//        (it is persistent)
//    ephemeral_state is not persistent - it's () for the first action of any new spend
//        but passed from the previous action in the same spend
//    new_conditions will be directly added to this puzzle's output conditions
//    but the finalizer puzzle is able to filter them after all actions are run

// Warning: This puzzle's finalizer likely assumes the singleton's amount is 1 (like the default one does).

import finalizer::*;
import merkle_utils::*;

fn item_in_list(item: Int, list: List<Int>) -> Bool {
    // if the item is not found in the whole list, (r ()) will
    //  generate an exception anyway
    inline let (first_list_item, remaining_list) = unchecked_cast::<(Int, List<Int>)>(list);
    if first_list_item == item {
        true
    } else {
        item_in_list(item, remaining_list)
    }
}

export struct StateTruth {
    ephemeral_state: Any,
    ...actual_state: Any,
} 

struct ActionOutput {
    state_truth: StateTruth,
    ...conditions: List<Condition>,
}

type ActionPuzzles = Any;
type ActionPuzzle = fn(state_truth: StateTruth, ...solutions: Solution) -> ActionOutput;
type Solution = Any;
type Selector = fn(...puzzles: ActionPuzzles) -> ActionPuzzle;

fn reduce_and_verify_proofs(
    MERKLE_ROOT: Bytes32,
    puzzles: ActionPuzzles,
    selectors_so_far: List<Selector>,
    selectors_and_proofs: List<(Selector, MerkleProof | nil)>,
) -> List<Selector> {
    if selectors_and_proofs is nil {
        selectors_so_far
    } else {
        inline let (selector, proof) = selectors_and_proofs.first;

        let valid_selector = if proof is nil {
            // treat selectors as ints for item_in_list
            item_in_list(
                unchecked_cast::<Int>(selector),
                unchecked_cast::<List<Int>>(selectors_so_far)
            )
        } else {
            MERKLE_ROOT == simplify_merkle_proof(tree_hash(selector(...puzzles)), proof)
        };
        assert valid_selector;

        reduce_and_verify_proofs(
            MERKLE_ROOT,
            puzzles,
            (selector, selectors_so_far),
            selectors_and_proofs.rest,
        )
    }
}

fn run_actions(
    puzzles: ActionPuzzles,
    current_conditions: List<List<Condition>>,
    action_output: ActionOutput,
    pending_selectors: List<Selector>,
    pending_solutions: List<Solution>,
) -> (StateTruth, List<List<Condition>>) {
    inline let ephemeral_and_actual_state = action_output.state_truth;
    inline let new_conditions = action_output.conditions;

    if pending_selectors is nil {
        (
            ephemeral_and_actual_state,
            (new_conditions, current_conditions),
        )
    } else {
        inline let selector = pending_selectors.first;
        inline let remaining_selectors = pending_selectors.rest;
        inline let (solution, remaining_solutions) = unchecked_cast::<(Solution, List<Solution>)>(pending_solutions);

        let puzzle = selector(...puzzles);

        run_actions(
            puzzles,
            (new_conditions, current_conditions),
            puzzle(ephemeral_and_actual_state, ...solution),
            remaining_selectors,
            remaining_solutions,
        )
    }
}

fn main(
    FINALIZER: Finalizer<StateTruth>,
    MERKLE_ROOT: Bytes32,
    STATE: Any,
    puzzles: ActionPuzzles,
    selectors_and_proofs: List<(Selector, MerkleProof | nil)>,
    solutions: List<Solution>,
    ...finalizer_solution: Any,
) -> List<Condition> {
    assert !(selectors_and_proofs is nil);

    let selectors = reduce_and_verify_proofs(
        MERKLE_ROOT,
        puzzles,
        nil,
        selectors_and_proofs
    );

    let run_action_output = run_actions(
        puzzles,
        nil,
        ActionOutput {
            state_truth: StateTruth {
                ephemeral_state: nil,
                actual_state: STATE,
            },
            conditions: nil,
        },
        selectors,
        solutions,
    );

    FINALIZER(
        FinalizerTruths {
            Merkle_Root: MERKLE_ROOT,
            State: STATE,
        },
        run_action_output,
        ...finalizer_solution,
    )
}

// finalizer.rue by yakuhito
// This puzzle is essentially used in the singleton action layer to 'finalize' a set of actions
// The current one only re-creates the singleton, but advanced dApps could use it to create other
//  conditions based on the final state - e.g., re-create the singleton's reserves or modify merkle root

// Note: This finalizer assumes sets the next singleton's amount to 1.

import action::StateTruth;

export struct FinalizerTruths {
    Merkle_Root: Bytes32,
    ...State: Any,
}

export type Finalizer<S> = fn(
    truths: FinalizerTruths,
    run_action_output: (S,List<List<Condition>>),
    ...finalizer_solution: Any
) -> List<Condition>;

fn flatten_list(list: List<List<Condition>>) -> List<Condition> {
    inline let (first_thing, the_rest) = unchecked_cast::<(List<Condition>, List<List<Condition>>)>(list);

    if first_thing is nil {
        if the_rest is nil { 
            nil
         } else {
            flatten_list(the_rest)
        }
    } else {
        (
            first_thing.first,
            flatten_list((first_thing.rest, the_rest))
        )
    }
}

fn main(
    ACTION_LAYER_MOD_HASH: Bytes32,
    HINT: Bytes32,
    // 2nd curry
    FINALIZER_SELF_HASH: Bytes32,
    Truth: FinalizerTruths,
    last_action_output: (StateTruth, List<List<Condition>>),
    ..._my_solution: Any // not used here
) -> List<Condition> {
    let recreation_condition = CreateCoin {
        puzzle_hash: curry_tree_hash(
            ACTION_LAYER_MOD_HASH,
            [
                curry_tree_hash(
                    FINALIZER_SELF_HASH,
                    [
                        tree_hash_atom(FINALIZER_SELF_HASH),
                    ]
                ), // finalizer puzzle hash
                tree_hash_atom(Truth.Merkle_Root),
                tree_hash(last_action_output.first.actual_state)
            ]
        ), // new inner ph
        amount: 1,
        memos: Memos {
            value: [HINT],
        }
    };

    [
        recreation_condition,
        ...flatten_list(last_action_output.rest)
    ]
}

// merkle_utils.rue by yakuhito

export struct MerkleProof {
    path: Int,
    ...hashes: List<Bytes32>,
}

export fn calculate_merkle_root(
    path: Int,
    current_hash: Bytes32,
    additional_steps: List<Bytes32>,
) -> Bytes32 {
    if additional_steps is nil {
        current_hash
    } else {
        calculate_merkle_root(
            path >>> 1,
            tree_hash_pair(
                inline if path & 1 != 0 {
                    additional_steps.first
                } else {
                    current_hash
                },
                inline if path & 1 != 0 {
                    current_hash
                } else {
                    additional_steps.first
                }
            ),
            additional_steps.rest
        )
    }
}

export fn simplify_merkle_proof_after_leaf(
    leaf_hash: Bytes32,
    proof: MerkleProof,
) -> Bytes32 {
    if proof.hashes is nil {
        leaf_hash
    } else {
        simplify_merkle_proof_after_leaf(
            tree_hash_pair(
                inline if proof.path & 1 != 0 {
                    proof.hashes.first
                } else {
                    leaf_hash
                },
                inline if proof.path & 1 != 0 {
                    leaf_hash
                } else {
                    proof.hashes.first
                }
            ),
            MerkleProof {
                path: proof.path >>> 1,
                hashes: proof.hashes.rest
            }
        )
    }
}

export inline fn simplify_merkle_proof(
    leaf: Bytes32,
    proof: MerkleProof,
) -> Bytes32 {
    simplify_merkle_proof_after_leaf(tree_hash_atom(leaf), proof)
}

// slot.clsp by yakuhito
// A singleton slot coin is created to store values that may be read at a later spend
// To read the values, the singleton will spend the slot coin - so the values are only readable once
// Might be helpful to think of this as a one-time ticket

// Double currying allows the controller singleton to only care about the 1st curry hash, which means it
//   only needs that and VALUE_HASH to build the full slot puzzle hash. This leads to more cost saved.
// NONCE is used to differentiate between slot types - it avoids situations where slots representing
//   two separate things but that hold the same value format (e.g., list of 3 numbers) can be confused.

// Warning: Slots do not assure uniqueness - a double-linked sorted list structure on top is required for that
//          An attacker might intentionally omit a given slot to trick the dApp that it doesn't exist
//          For example, a naive handle reigstration app might be tricked into registering the same handle twice`

import super::common_types::*;

struct SingletonInfo {
    singleton_mod_hash: Bytes32,
    ...singleton_struct_hash: Bytes32, // treehash of full singleton struct
}

fn singleton_full_puzzle_hash(
    CONTROLLER_SINGLETON_INFO: SingletonInfo,
    inner_puzzle_hash: Bytes32,
) -> Bytes32 {
    curry_tree_hash(
        CONTROLLER_SINGLETON_INFO.singleton_mod_hash,
        [
            CONTROLLER_SINGLETON_INFO.singleton_struct_hash,
            inner_puzzle_hash,
        ]
    )
}

fn main(
    CONTROLLER_SINGLETON_INFO: SingletonInfo,
    // different nonces will hold different data types
    _NONCE: Any,
    // 2nd curry
    _VALUE_HASH: Bytes32,
    // info about this coin's parent (previous singleton coin)
    parent_proof: CompactCoinProof,
    // info about this coin's spender (current singleton coin - the one consuming the value)
    ...spender_inner_puzzle_hash: Bytes32,
) -> List<Condition> {
    [
        AssertMyParentId {
            parent_id: coinid(
                parent_proof.parent_info,
                singleton_full_puzzle_hash(CONTROLLER_SINGLETON_INFO, parent_proof.inner_puzzle_hash),
                parent_proof.amount,
            ),
        },
        ReceiveMessage {
            mode: SENDER_PUZZLE | RECEIVER_PUZZLE,
            message: nil,
            sender: [
                singleton_full_puzzle_hash(CONTROLLER_SINGLETON_INFO, spender_inner_puzzle_hash)
            ],
        }
    ]
}

